"""Layer 5 -- every figure in the paper, regenerated by one command.

Each function takes the results DataFrame and writes one artifact. They are
deliberately independent: a figure whose data does not exist yet is skipped with
a message rather than crashing the target, which is what lets `make figures` be
run from day one and grow into a complete figure set as each layer lands.
"""

from __future__ import annotations

from pathlib import Path

import matplotlib.pyplot as plt
import numpy as np
import pandas as pd

from gib.analysis import load as L
from gib.analysis.style import (
    AXIS_COLORS,
    TAXONOMY_COLORS,
    TAXONOMY_LABELS,
    annotate_thin_cells,
    apply_style,
    model_style,
    savefig,
)
from gib.eval.metrics.calibration import expected_calibration_error, overconfidence_rate
from gib.eval.metrics.robustness import fit_decay, robustness_score

# --------------------------------------------------------------------------- #
# Axis 1 -- decay curves
# --------------------------------------------------------------------------- #


def fig_decay_curves(df: pd.DataFrame, out: Path, simulated: bool = False) -> dict:
    """Accuracy vs. distractor count, with the fitted exponential and lambda.

    Lambda is printed in the legend because a single scalar per model is far more
    quotable than a curve, and it is what makes models rankable on this axis.
    """
    tbl = L.decay_table(df)
    if tbl.empty:
        return {}

    apply_style()
    fig, ax = plt.subplots(figsize=(6.2, 4.0))
    styles = model_style(sorted(tbl["model"].unique()))
    fits: dict[str, dict] = {}

    for model, g in tbl.groupby("model"):
        g = g.sort_values("n_distractors")
        s = styles[model]
        fit = fit_decay(g["n_distractors"].values, g["accuracy"].values, weights=g["n"].values)
        fits[model] = fit.as_dict()

        ax.plot(g["n_distractors"], g["accuracy"], s["marker"], color=s["color"],
                alpha=0.85, label=None, zorder=3)
        if fit.converged and not np.isnan(fit.lam):
            xs = np.linspace(0, g["n_distractors"].max(), 200)
            ax.plot(xs, fit.predict(xs), color=s["color"], linestyle=s["linestyle"],
                    label=f"{model}  (λ={fit.lam:.3f})", zorder=2)
        else:
            ax.plot(g["n_distractors"], g["accuracy"], color=s["color"],
                    linestyle=s["linestyle"], label=f"{model}  (fit failed)", zorder=2)

    ax.set_xlabel("Number of hard-negative distractor documents")
    ax.set_ylabel("Accuracy")
    ax.set_title("Axis 1 — Retrieval noise: dosage–response decay")
    ax.set_ylim(0, 1)
    ax.legend(loc="upper right", ncol=1)
    ax.text(0.01, -0.16, r"fit: $acc(d) = a\,e^{-\lambda d} + c$; ground truth always present",
            transform=ax.transAxes, fontsize=7, color="#555")

    savefig(fig, out / "fig1_decay_curves.png", simulated=simulated)
    return fits


# --------------------------------------------------------------------------- #
# Axis 2 -- resolution thresholds
# --------------------------------------------------------------------------- #


def fig_resolution_thresholds(df: pd.DataFrame, out: Path, simulated: bool = False) -> dict:
    """Accuracy vs. degradation dose, one panel per degradation family."""
    tbl = L.visual_table(df)
    if tbl.empty:
        return {}

    families = [f for f in ("gaussian_blur", "motion_blur", "crop") if f in set(tbl["degradation"])]
    if not families:
        return {}

    apply_style()
    fig, axes = plt.subplots(1, len(families), figsize=(4.0 * len(families), 3.6), squeeze=False)
    styles = model_style(sorted(tbl["model"].unique()))
    clean = L.clean_accuracy(df)
    labels = {
        "gaussian_blur": ("Gaussian blur σ", "σ"),
        "motion_blur": ("Motion-blur kernel (px)", "px"),
        "crop": ("Fraction of answer object visible", "visible"),
    }

    for ax, fam in zip(axes[0], families):
        sub = tbl[tbl["degradation"] == fam]
        for model, g in sub.groupby("model"):
            g = g.sort_values("degradation_param")
            s = styles[model]
            ax.plot(g["degradation_param"], g["accuracy"], marker=s["marker"],
                    color=s["color"], linestyle=s["linestyle"], label=model)
            if model in clean.index:
                ax.axhline(clean[model], color=s["color"], alpha=0.25, linewidth=0.8)
        ax.set_xlabel(labels[fam][0])
        ax.set_title(fam.replace("_", " ").title())
        ax.set_ylim(0, 1)
        if fam == "crop":
            ax.invert_xaxis()  # harder to the right, like the other panels

    axes[0][0].set_ylabel("Accuracy")
    axes[0][-1].legend(loc="best")
    fig.suptitle("Axis 2 — Visual ambiguity: dosage–response (horizontal lines = clean accuracy)",
                 y=1.02)

    savefig(fig, out / "fig2_resolution_thresholds.png", simulated=simulated)
    return {"families": families}


def fig_chair_thresholds(chair_by_model: dict, out: Path, simulated: bool = False) -> dict:
    """CHAIR vs. degradation dose, with the Resolution Threshold marked.

    The threshold is defined as the first dose where CHAIR exceeds clean by more
    than 10 points -- the point where the model stops seeing and starts guessing.
    """
    if not chair_by_model:
        return {}

    apply_style()
    fig, ax = plt.subplots(figsize=(6.2, 4.0))
    styles = model_style(sorted(chair_by_model))
    thresholds = {}

    for model, series in sorted(chair_by_model.items()):
        doses = sorted(series["by_dose"])
        vals = [series["by_dose"][d] * 100 for d in doses]
        clean = series["clean"] * 100
        s = styles[model]
        ax.plot(doses, vals, marker=s["marker"], color=s["color"], linestyle=s["linestyle"],
                label=model)
        ax.axhline(clean + 10, color=s["color"], alpha=0.2, linewidth=0.8)

        thr = next((d for d, v in zip(doses, vals) if v - clean > 10), None)
        thresholds[model] = thr
        if thr is not None:
            ax.axvline(thr, color=s["color"], alpha=0.35, linestyle=":", linewidth=1.0)
            ax.plot([thr], [dict(zip(doses, vals))[thr]], marker="*", markersize=13,
                    color=s["color"], zorder=5)

    ax.set_xlabel("Gaussian blur σ")
    ax.set_ylabel("CHAIR$_i$ (%)")
    ax.set_title("Resolution Threshold — where seeing becomes guessing\n"
                 "(★ = first dose with CHAIR > clean + 10 pts)")
    ax.legend(loc="best")

    savefig(fig, out / "fig3_chair_resolution_threshold.png", simulated=simulated)
    return {"thresholds": thresholds}


# --------------------------------------------------------------------------- #
# The Vulnerability Heatmap
# --------------------------------------------------------------------------- #


def fig_vulnerability_heatmap(df: pd.DataFrame, out: Path, simulated: bool = False) -> dict:
    """Δ-accuracy vs. clean over the blur x noise grid, one panel per model plus
    a mean panel. The paper's most shareable figure."""
    grid = L.heatmap_table(df)
    if grid.empty:
        return {}

    models = sorted(grid["model"].unique())
    n_panels = len(models) + 1
    ncols = min(3, n_panels)
    nrows = int(np.ceil(n_panels / ncols))

    apply_style()
    # constrained layout: with a shared colorbar attached to the whole axes grid,
    # the default layout lets each row's titles collide with the row above's
    # x-labels.
    fig, axes = plt.subplots(
        nrows, ncols, figsize=(3.6 * ncols, 3.5 * nrows), squeeze=False, layout="constrained"
    )
    flat = [a for row in axes for a in row]

    sigmas = sorted(grid["degradation_param"].unique())
    dists = sorted(grid["n_distractors"].unique())

    def pivot(sub):
        m = np.full((len(sigmas), len(dists)), np.nan)
        for _, r in sub.iterrows():
            m[sigmas.index(r["degradation_param"]), dists.index(r["n_distractors"])] = r["delta"]
        return m

    mats = {mdl: pivot(grid[grid["model"] == mdl]) for mdl in models}
    mats["mean (all models)"] = np.nanmean(np.stack(list(mats.values())), axis=0)

    # One shared symmetric scale so panels are visually comparable; a per-panel
    # scale would make a robust model's mild drop look as alarming as a
    # fragile model's collapse.
    vmax = float(np.nanmax(np.abs(np.stack(list(mats.values())))))
    vmax = max(vmax, 1e-6)

    im = None
    for ax, (title, mat) in zip(flat, mats.items()):
        im = ax.imshow(mat, cmap="RdBu", vmin=-vmax, vmax=vmax, aspect="auto", origin="upper")
        ax.set_xticks(range(len(dists)), [f"{int(d)}" for d in dists])
        ax.set_yticks(range(len(sigmas)), [f"{s:g}" for s in sigmas])
        ax.set_xlabel("Retrieval noise (# distractors)")
        ax.set_ylabel("Visual blur (σ)")
        ax.set_title(title, fontsize=9)
        ax.grid(False)
        for i in range(mat.shape[0]):
            for j in range(mat.shape[1]):
                if not np.isnan(mat[i, j]):
                    ax.text(j, i, f"{mat[i,j]*100:+.0f}", ha="center", va="center",
                            fontsize=6.5,
                            color="white" if abs(mat[i, j]) > vmax * 0.55 else "#222")

    for ax in flat[len(mats):]:
        ax.axis("off")

    if im is not None:
        cbar = fig.colorbar(im, ax=axes, shrink=0.75, pad=0.02)
        cbar.set_label("Δ accuracy vs. clean")

    thin = int(grid["thin_cell"].sum())
    annotate_thin_cells(flat[0], thin, len(grid))
    # No explicit y: constrained layout reserves space for the suptitle itself,
    # and pinning it would push it back onto the first row of titles.
    fig.suptitle("The Vulnerability Heatmap — combined visual × retrieval stress")

    savefig(fig, out / "fig4_vulnerability_heatmap.png", simulated=simulated)
    return {"n_cells": len(grid), "thin_cells": thin}


# --------------------------------------------------------------------------- #
# The Conflict Matrix + counterfactual symmetry
# --------------------------------------------------------------------------- #


def fig_conflict_matrix(df: pd.DataFrame, out: Path, simulated: bool = False) -> dict:
    """Trust Index and taxonomy shares per model, with the bias verdict."""
    tbl = L.conflict_table(df)
    if tbl.empty:
        return {}

    apply_style()
    fig, (ax1, ax2) = plt.subplots(
        1, 2, figsize=(11.0, 0.55 * len(tbl) + 2.6),
        gridspec_kw={"width_ratios": [1.05, 1.35]},
    )

    y = np.arange(len(tbl))
    colors = ["#D55E00" if v > 0.55 else "#0072B2" if v < 0.45 else "#7F7F7F"
              for v in tbl["trust_index"]]
    ax1.barh(y, tbl["trust_index"], color=colors, alpha=0.9)
    ax1.axvline(0.5, color="black", linestyle="--", linewidth=1.0)
    ax1.set_yticks(y, tbl["model"])
    ax1.invert_yaxis()
    ax1.set_xlim(0, 1)
    ax1.set_xlabel("Trust Index   →  text-biased")
    ax1.set_title("Trust Index under cross-modal conflict")
    for i, (v, verdict) in enumerate(zip(tbl["trust_index"], tbl["verdict"])):
        if not np.isnan(v):
            ax1.text(min(v + 0.02, 0.97), i, verdict, va="center", fontsize=7.5)
    ax1.text(0.01, -0.09, "TI = P(textual) / [P(textual) + P(visual)];  0.5 = no preference",
             transform=ax1.transAxes, fontsize=7, color="#555")

    modes = ["correct", "knowledge_inertia", "sensory_capture", "reasoning_collapse"]
    left = np.zeros(len(tbl))
    for mode in modes:
        vals = tbl[mode].values if mode in tbl else np.zeros(len(tbl))
        if mode == "correct":
            vals = tbl["accuracy"].values
        ax2.barh(y, vals, left=left, color=TAXONOMY_COLORS[mode],
                 label=TAXONOMY_LABELS[mode], alpha=0.92)
        left += np.nan_to_num(vals)
    ax2.set_yticks(y, [""] * len(tbl))
    ax2.invert_yaxis()
    ax2.set_xlim(0, 1)
    ax2.set_xlabel("Proportion of items")
    ax2.set_title("Failure taxonomy under conflict")
    ax2.legend(loc="lower right", ncol=2, fontsize=7.5)

    savefig(fig, out / "fig5_conflict_matrix.png", simulated=simulated)
    return tbl.to_dict("records")


def fig_counterfactual_symmetry(df: pd.DataFrame, out: Path, simulated: bool = False) -> dict:
    """Does the text bias flip symmetrically, or is it object-dependent?

    Each point is one counterfactual twin pair. Points on the diagonal mean the
    model treated both directions identically -- a genuine modality preference.
    Systematic departure means the "bias toward text" is really a preference for
    particular entities, which is a substantially weaker claim.
    """
    tbl = L.twin_table(df)
    if tbl.empty:
        return {}

    models = sorted(tbl["model"].unique())
    apply_style()
    fig, axes = plt.subplots(1, len(models), figsize=(3.3 * len(models), 3.4), squeeze=False)
    styles = model_style(models)
    summary = {}

    for ax, model in zip(axes[0], models):
        g = tbl[tbl["model"] == model]
        s = styles[model]
        ax.scatter(g["ti_a"], g["ti_b"], s=16, alpha=0.55, color=s["color"], edgecolors="none")
        ax.plot([0, 1], [0, 1], color="#444", linestyle="--", linewidth=1.0)
        ax.axhline(0.5, color="#999", linewidth=0.6)
        ax.axvline(0.5, color="#999", linewidth=0.6)
        ax.set_xlim(0, 1); ax.set_ylim(0, 1)
        ax.set_xlabel("Trust Index (original)")
        ax.set_title(model, fontsize=9)
        sym = float(g["symmetry"].mean(skipna=True))
        summary[model] = {"symmetry": sym, "n_pairs": len(g)}
        ax.text(0.04, 0.94, f"symmetry {sym:.3f}\nn={len(g)}", transform=ax.transAxes,
                fontsize=7.5, va="top")

    axes[0][0].set_ylabel("Trust Index (flipped twin)")
    fig.suptitle("Counterfactual probing — is text bias symmetric or object-dependent?", y=1.03)

    savefig(fig, out / "fig6_counterfactual_symmetry.png", simulated=simulated)
    return summary


# --------------------------------------------------------------------------- #
# Robustness and the Pareto frontier
# --------------------------------------------------------------------------- #


def compute_robustness(df: pd.DataFrame) -> pd.DataFrame:
    """R per model, per axis and pooled."""
    clean = L.clean_accuracy(df)
    rows = []
    for model, g in df.groupby("model"):
        acc_clean = clean.get(model, float("nan"))
        n_clean = int((g["axis"] == "clean").sum())
        track = g["track"].iloc[0]

        for axis in ("noise", "visual", "conflict", "combined", "__pooled__"):
            sub = g[g["axis"] != "clean"] if axis == "__pooled__" else g[g["axis"] == axis]
            if sub.empty:
                continue
            cal = expected_calibration_error(sub["confidence"].values, sub["is_correct"].values)
            r = robustness_score(
                acc_clean, float(sub["is_correct"].mean()), cal.ece,
                n_clean, len(sub), track,
            )
            rows.append(
                {
                    "model": model, "axis": "pooled" if axis == "__pooled__" else axis,
                    "track": track, **r.as_dict(),
                    "overconfidence_rate": overconfidence_rate(
                        sub["confidence"].values, sub["is_correct"].values
                    ),
                }
            )
    return pd.DataFrame(rows)


def fig_pareto_frontier(df: pd.DataFrame, out: Path, simulated: bool = False) -> dict:
    """Clean accuracy (x) vs. Robustness Score R (y), one point per model.

    If the frontier slopes down -- the strongest clean models are the most
    fragile -- that is the paper's headline scatter. If it does not, that is
    still a finding, and the fitted trend line is annotated either way rather
    than only when it says what we hoped.
    """
    rob = compute_robustness(df)
    pooled = rob[rob["axis"] == "pooled"]
    if pooled.empty:
        return {}

    apply_style()
    fig, ax = plt.subplots(figsize=(6.0, 4.4))
    styles = model_style(sorted(pooled["model"]))

    for _, r in pooled.iterrows():
        s = styles[r["model"]]
        ax.scatter(r["acc_clean"], r["robustness_r"], s=130, color=s["color"],
                   marker=s["marker"], edgecolors="white", linewidths=1.2, zorder=3)
        ax.annotate(f"{r['model']}\n(track {r['track']})",
                    (r["acc_clean"], r["robustness_r"]),
                    textcoords="offset points", xytext=(9, -4), fontsize=7.5)

    x = pooled["acc_clean"].values.astype(float)
    y = pooled["robustness_r"].values.astype(float)
    mask = ~np.isnan(x) & ~np.isnan(y)
    slope = float("nan")
    if mask.sum() >= 3:
        slope, intercept = np.polyfit(x[mask], y[mask], 1)
        xs = np.linspace(x[mask].min(), x[mask].max(), 100)
        ax.plot(xs, slope * xs + intercept, color="#444", linestyle="--", linewidth=1.2,
                zorder=2)
        verdict = ("stronger clean models are MORE fragile" if slope < 0
                   else "stronger clean models are also more robust")
        ax.text(0.02, 0.03, f"trend slope = {slope:+.3f}\n{verdict}",
                transform=ax.transAxes, fontsize=8, va="bottom",
                bbox=dict(boxstyle="round,pad=0.4", facecolor="#F4F4F4", edgecolor="#CCC"))

    ax.set_xlabel("Clean accuracy")
    ax.set_ylabel(r"Robustness Score  $\mathcal{R} = \frac{Acc_{adverse}}{Acc_{clean}}\times(1-ECE)$")
    ax.set_title("The Pareto Frontier of Robustness")
    # Point labels are drawn to the right of each marker; without headroom the
    # rightmost model's name runs off the canvas.
    ax.margins(x=0.22, y=0.12)

    savefig(fig, out / "fig7_pareto_frontier.png", simulated=simulated)
    return {"slope": slope, "table": pooled.to_dict("records")}


def fig_robustness_by_axis(df: pd.DataFrame, out: Path, simulated: bool = False) -> dict:
    """Grouped bars: R per model per axis."""
    rob = compute_robustness(df)
    per_axis = rob[rob["axis"] != "pooled"]
    if per_axis.empty:
        return {}

    models = sorted(per_axis["model"].unique())
    axes_order = [a for a in ("noise", "visual", "conflict", "combined")
                  if a in set(per_axis["axis"])]

    apply_style()
    fig, ax = plt.subplots(figsize=(1.5 * len(models) + 3.0, 4.0))
    width = 0.8 / max(1, len(axes_order))
    xs = np.arange(len(models))

    for i, axis in enumerate(axes_order):
        vals = [
            per_axis[(per_axis["model"] == m) & (per_axis["axis"] == axis)]["robustness_r"].mean()
            for m in models
        ]
        ax.bar(xs + i * width - 0.4 + width / 2, vals, width=width * 0.92,
               color=AXIS_COLORS.get(axis, "#888"), label=axis, alpha=0.92)

    ax.set_xticks(xs, models, rotation=18, ha="right")
    ax.set_ylabel(r"Robustness Score $\mathcal{R}$")
    ax.set_title("Robustness by stressor axis")
    ax.legend(title="axis", ncol=len(axes_order))

    savefig(fig, out / "fig8_robustness_by_axis.png", simulated=simulated)
    return rob.to_dict("records")


# --------------------------------------------------------------------------- #
# Taxonomy, calibration, human gap
# --------------------------------------------------------------------------- #


def fig_taxonomy_by_axis(df: pd.DataFrame, out: Path, simulated: bool = False) -> dict:
    """Stacked failure-mode shares per model x axis.

    This is the figure that only exists because the falsehood was encoded in the
    data: it reports taxonomy proportions over the whole corpus rather than over
    a hand-labelled subset.
    """
    tax = L.taxonomy_proportions(df, "model", "axis")
    if tax.empty:
        return {}

    models = sorted(tax["model"].unique())
    axes_order = [a for a in ("clean", "noise", "visual", "conflict", "combined")
                  if a in set(tax["axis"])]

    apply_style()
    fig, axs = plt.subplots(1, len(models), figsize=(2.7 * len(models), 3.8), squeeze=False,
                            sharey=True)

    for ax, model in zip(axs[0], models):
        sub = tax[tax["model"] == model]
        xs = np.arange(len(axes_order))
        bottom = np.zeros(len(axes_order))
        for mode in ("correct", "knowledge_inertia", "sensory_capture", "reasoning_collapse"):
            vals = [
                float(sub[(sub["axis"] == a) & (sub["failure_mode"] == mode)]["proportion"].sum())
                for a in axes_order
            ]
            ax.bar(xs, vals, bottom=bottom, color=TAXONOMY_COLORS[mode],
                   label=TAXONOMY_LABELS[mode], alpha=0.93)
            bottom += np.array(vals)
        ax.set_xticks(xs, axes_order, rotation=35, ha="right")
        ax.set_title(model, fontsize=9)
        ax.set_ylim(0, 1)

    axs[0][0].set_ylabel("Proportion of items")
    handles, labels = axs[0][0].get_legend_handles_labels()
    fig.legend(handles, labels, loc="lower center", ncol=4, bbox_to_anchor=(0.5, -0.09))
    fig.suptitle("Failure taxonomy by model and stressor axis", y=1.02)

    savefig(fig, out / "fig9_taxonomy_by_axis.png", simulated=simulated)
    return tax.to_dict("records")


def fig_calibration(df: pd.DataFrame, out: Path, simulated: bool = False) -> dict:
    """Reliability diagrams -- the visual form of the "confident but wrong"
    pathology that the Robustness Score penalises."""
    adverse = df[df["axis"] != "clean"]
    if adverse.empty or adverse["confidence"].isna().all():
        return {}

    models = sorted(adverse["model"].unique())
    ncols = min(3, len(models))
    nrows = int(np.ceil(len(models) / ncols))

    apply_style()
    fig, axs = plt.subplots(nrows, ncols, figsize=(3.2 * ncols, 3.0 * nrows), squeeze=False)
    flat = [a for row in axs for a in row]
    out_stats = {}

    for ax, model in zip(flat, models):
        g = adverse[adverse["model"] == model]
        cal = expected_calibration_error(g["confidence"].values, g["is_correct"].values)
        out_stats[model] = cal.as_dict()

        centers = [(cal.bin_edges[i] + cal.bin_edges[i + 1]) / 2 for i in range(cal.n_bins)]
        ax.bar(centers, cal.bin_acc, width=0.09, color="#0072B2", alpha=0.85, label="accuracy")
        ax.plot([0, 1], [0, 1], "--", color="#444", linewidth=1.0, label="perfect calibration")
        ax.set_xlim(0, 1); ax.set_ylim(0, 1)
        ax.set_title(f"{model}\nECE={cal.ece:.3f}  n={cal.n}", fontsize=8.5)
        ax.set_xlabel("Confidence")

    for ax in flat[len(models):]:
        ax.axis("off")
    axs[0][0].set_ylabel("Accuracy")
    axs[0][0].legend(fontsize=7)
    fig.suptitle("Calibration under adversarial conditions (bars below the diagonal = overconfident)",
                 y=1.01)

    savefig(fig, out / "fig10_calibration.png", simulated=simulated)
    return out_stats


def fig_human_gap(df: pd.DataFrame, human_summary: dict, out: Path, simulated: bool = False) -> dict:
    """The Reasoning Gap: human vs. model accuracy per stressor.

    Every cell both cover is plotted, including the ones where the gap narrows.
    Showing the narrowing case is what makes the study credible.
    """
    if not human_summary or "by_axis" not in human_summary:
        return {}

    model_acc = df.groupby(["model", "axis"])["is_correct"].mean().unstack(fill_value=np.nan)
    axes_order = [a for a in ("clean", "noise", "visual", "conflict", "combined")
                  if a in human_summary["by_axis"] and a in model_acc.columns]
    if not axes_order:
        return {}

    apply_style()
    fig, ax = plt.subplots(figsize=(1.3 * len(axes_order) + 4.0, 4.2))
    xs = np.arange(len(axes_order))
    models = sorted(model_acc.index)
    styles = model_style(models)
    width = 0.8 / (len(models) + 1)

    human_vals = [human_summary["by_axis"][a]["accuracy"] for a in axes_order]
    ax.bar(xs - 0.4 + width / 2, human_vals, width=width * 0.92, color="#111",
           label="Human", alpha=0.9)

    for i, m in enumerate(models, start=1):
        vals = [model_acc.loc[m, a] for a in axes_order]
        ax.bar(xs - 0.4 + i * width + width / 2, vals, width=width * 0.92,
               color=styles[m]["color"], label=m, alpha=0.9)

    ax.set_xticks(xs, axes_order)
    ax.set_ylabel("Accuracy")
    ax.set_ylim(0, 1)
    ax.set_title("The Reasoning Gap — humans vs. models by stressor")
    ax.legend(ncol=2, fontsize=7.5)

    savefig(fig, out / "fig11_human_gap.png", simulated=simulated)
    return {"axes": axes_order, "human": human_vals}


def fig_position_bias(df: pd.DataFrame, out: Path, simulated: bool = False) -> dict:
    """Accuracy by the ground-truth document's position in the retrieved list."""
    tbl = L.position_bias_table(df)
    if tbl.empty:
        return {}

    apply_style()
    fig, ax = plt.subplots(figsize=(6.0, 3.6))
    styles = model_style(sorted(tbl["model"].unique()))
    for model, g in tbl.groupby("model"):
        g = g.sort_values("gt_doc_position")
        s = styles[model]
        ax.plot(g["gt_doc_position"], g["accuracy"], marker=s["marker"], color=s["color"],
                linestyle=s["linestyle"], label=model)

    ax.set_xlabel("Position of the ground-truth document among retrieved passages")
    ax.set_ylabel("Accuracy")
    ax.set_title("Position bias (free ablation — positions logged at dataset build)")
    ax.set_ylim(0, 1)
    ax.legend(fontsize=7.5)

    savefig(fig, out / "fig12_position_bias.png", simulated=simulated)
    return tbl.to_dict("records")
